interface DomainResult {
  domain: string;
  registered: boolean;
  ip?: string;
  country?: string;
  registrar?: string;
  created?: string;
  risk: "high" | "medium" | "low" | "clean";
  flags: string[];
  whoisUrl?: string;
  virusTotalUrl?: string;
}

interface KeywordHit {
  type: "domain" | "social" | "app";
  name: string;
  url?: string;
  risk: "high" | "medium" | "low";
  description: string;
  discovered: string;
}

const TYPO_PATTERNS = [
  (b: string) => b.replace(/a/g, "4"),
  (b: string) => b.replace(/e/g, "3"),
  (b: string) => b.replace(/i/g, "1"),
  (b: string) => b.replace(/o/g, "0"),
  (b: string) => b.replace(/s/g, "5"),
  (b: string) => b + "-secure",
  (b: string) => b + "-login",
  (b: string) => b + "-verify",
  (b: string) => b + "-support",
  (b: string) => "secure-" + b,
  (b: string) => "login-" + b,
  (b: string) => "my" + b,
  (b: string) => b + "app",
  (b: string) => b + "portal",
  (b: string) => b.slice(0, -1) + b.slice(-1).repeat(2),
  (b: string) => b.replace(/l/g, "1"),
  (b: string) => b.replace(/rn/, "m"),
  (b: string) => b.replace(/cl/, "d"),
];

const TLDS = [".com", ".net", ".org", ".io", ".co", ".info", ".biz", ".xyz", ".online"];

function generateTypoSquatList(brand: string): string[] {
  const base = brand.toLowerCase().replace(/\s+/g, "");
  const variants = new Set<string>();
  TYPO_PATTERNS.forEach(fn => {
    const v = fn(base);
    if (v !== base) TLDS.forEach(tld => variants.add(v + tld));
  });
  // Homoglyphs
  const homoglyphs: Record<string, string> = { a: "а", e: "е", o: "о", p: "р", c: "с" };
  let homoglyphVersion = base;
  for (const [l, g] of Object.entries(homoglyphs)) {
    homoglyphVersion = homoglyphVersion.replace(new RegExp(l, "g"), g);
  }
  if (homoglyphVersion !== base) TLDS.slice(0, 3).forEach(tld => variants.add(homoglyphVersion + tld));
  return Array.from(variants).slice(0, 40);
}

async function checkDomainRisk(domain: string): Promise<DomainResult> {
  const flags: string[] = [];
  let risk: DomainResult["risk"] = "clean";

  // Check suspicious keywords in domain
  const suspiciousKeywords = ["login", "secure", "verify", "support", "account", "banking", "update"];
  const tldRed = [".xyz", ".online", ".info", ".biz", ".top", ".club", ".gq", ".tk", ".ml"];

  const tld = "." + domain.split(".").slice(-1)[0];
  if (tldRed.includes(tld)) { flags.push("Suspicious TLD"); risk = "medium"; }
  if (suspiciousKeywords.some(k => domain.includes(k))) { flags.push("Phishing keyword"); risk = "high"; }
  if (/\d{2,}/.test(domain.split(".")[0])) { flags.push("Numeric pattern"); if (risk !== "high") risk = "medium"; }
  if (domain.includes("-")) { flags.push("Hyphenated"); if (risk === "clean") risk = "low"; }

  // Query ThreatFox via proxy edge function for known malicious
  try {
    const { data } = await supabase.functions.invoke("proxy", {
      body: {
        url: `https://threatfox-api.abuse.ch/api/v1/`,
        method: "POST",
        body: JSON.stringify({ query: "search_ioc", search_term: domain }),
      },
    });
    if (data?.data?.length) {
      flags.push("Known IOC (ThreatFox)");
      risk = "high";
    }
  } catch { /* ignore */ }

  return {
    domain,
    registered: flags.length > 0,
    risk,
    flags: flags.length ? flags : ["No suspicious patterns detected"],
    virusTotalUrl: `https://www.virustotal.com/gui/domain/${domain}`,
    whoisUrl: `https://www.whois.com/whois/${domain}`,
  };
}

